const pages = $('Combine All Followers').first().json.data || [];
const larkItems = $input.item.json.data?.items || [];
const toCreate = [], toUpdate = [];

for (const page of pages) {
  const matched = larkItems.find(r => {
    const stored = r.fields?.['Page'];
    if (!stored) return false;
    return stored.trim() === page.Page.trim();
  });

  // Build update payload — only follower fields, leave other fields untouched
  const fields = {
    'Followers (IG)': page['Followers (IG)'] || 0,
    'Followers (FB)': page['Followers (FB)'] || 0,
    'Followers (TT)': page['Followers (TT)'] || 0
  };

  if (matched) {
    toUpdate.push({ record_id: matched.record_id, fields });
  } else {
    // Page row doesn't exist — skip rather than create (keeps team data integrity)
    console.log('Page not found in Lark, skipping: ' + page.Page);
  }
}

const results = [];
if (toUpdate.length > 0) results.push({ json: { operation: 'update', count: toUpdate.length, records: toUpdate } });
else results.push({ json: { operation: 'skip', count: 0, records: [] } });

console.log('Update batch size: ' + toUpdate.length);
return results;

const pages = $('Combine All Followers').first().json.data || [];
const MAP = {
  'KOOCESTER (Main)': { page: 'Koocester', country: 'Singapore' },
  'Homes SG': { page: 'Koocester Homes', country: 'Singapore' },
  'Homes MY': { page: 'Koocester Homes', country: 'Malaysia' },
  'Homes ID': { page: 'Koocester Homes', country: 'Indonesia' },
  'Business SG': { page: 'Koocester Business', country: 'Singapore' },
  'Business MY': { page: 'Koocester Business', country: 'Malaysia' },
  'Business ID': { page: 'Koocester Business', country: 'Indonesia' },
  'Autos SG': { page: 'Koocester Autos', country: 'Singapore' },
  'Autos MY': { page: 'Koocester Autos', country: 'Malaysia' },
  'Autos ID': { page: 'Koocester Autos', country: 'Indonesia' },
  'Wealth SG': { page: 'Koocester Wealth', country: 'Singapore' },
  'Wealth MY': { page: 'Koocester Wealth', country: 'Malaysia' },
  'Wealth ID': { page: 'Koocester Wealth', country: 'Indonesia' },
  'Foodie SG': { page: 'Koocester Foodie', country: 'Singapore' },
  'Foodie MY': { page: 'Koocester Foodie', country: 'Malaysia' },
  'Foodie ID': { page: 'Koocester Foodie', country: 'Indonesia' }
};
const FIELDS = [
  { f: 'Followers (IG)', platform: 'Instagram' },
  { f: 'Followers (FB)', platform: 'Facebook' },
  { f: 'Followers (TT)', platform: 'TikTok' }
];
const date = new Date(Date.now() + 8 * 3600 * 1000).toISOString().slice(0, 10);
const q = (s) => "'" + String(s).replace(/'/g, "''") + "'";
const rows = [];
for (const p of pages) {
  const m = MAP[p.Page];
  if (!m) { console.log('Unmapped page: ' + p.Page); continue; }
  for (const fld of FIELDS) {
    const followers = Number(p[fld.f]) || 0;
    const rid = date + '_' + m.page + '_' + fld.platform + '_' + m.country;
    rows.push('(' + q(rid) + ', DATE ' + q(date) + ', ' + q(m.page) + ', ' + q(fld.platform) + ', ' + q(m.country) + ', ' + followers + ', now())');
  }
}
if (rows.length === 0) { throw new Error('Build Supabase Rows: no rows built'); }
const sql = 'INSERT INTO content_perf.metricool_snapshots (record_id, snapshot_date, page, platform, country, followers, loaded_at) VALUES ' + rows.join(', ') + ' ON CONFLICT (record_id) DO UPDATE SET followers = EXCLUDED.followers, snapshot_date = EXCLUDED.snapshot_date, loaded_at = now();';
return [{ json: { query: sql, rowCount: rows.length, date: date } }];

